# -*- coding: utf-8 -*-
# Задание №5: эталонное решение ученика (Python). Независимая реализация правил — через format(n, 'b') и int(..., 2).
# Запуск: python solve.py запрос.json   (формат запроса — см. tests/*.json)
import sys, json


def make_f(rule, p):
    b2 = lambda n: format(n, 'b')
    if rule == 'A':
        return lambda n: int((p['el'] + b2(n) + p['er']) if n % 2 == 0 else (p['ol'] + b2(n) + p['orr']), 2)
    if rule == 'B':
        def f(n):
            m = p['em'] if n % 2 == 0 else p['om']
            return int(''.join(m[c] if c in m else c for c in b2(n)), 2)
        return f
    if rule == 'C':
        def f(n):
            s = b2(n)
            for _ in range(p['times']):
                bit = '1' if s.count('1') % 2 == 1 else '0'
                if p['flip']:
                    bit = '0' if bit == '1' else '1'
                s = s + bit if p['side'] == 'r' else bit + s
            return int(s, 2)
        return f
    if rule == 'D':
        def f(n):
            for _ in range(p['times']):
                r = format(n % p['k'], 'b')
                s = b2(n)
                n = int(s + r if p['side'] == 'r' else r + s, 2)
            return n
        return f
    if rule == 'E':
        def f(n):
            s = b2(n)
            c = s.translate(str.maketrans('01', '10'))
            if n % 2 == 0:
                t = s + c if p['es'] == 'r' else c + s
            else:
                c = p['oextra'] + c
                t = s + c if p['os_'] == 'r' else c + s
            return int(t, 2)
        return f
    if rule == 'F':
        pairs = {3: [(0, 1), (1, 2)], 4: [(0, 1), (2, 3)], -4: [(0, 1), (1, 2), (2, 3)]}[p['d']]
        def f(n):
            d = list(map(int, str(n)))
            s = sorted((d[i] + d[j] for i, j in pairs), reverse=(p['order'] == 'desc'))
            return int(''.join(str(x) for x in s))
        return f


def main():
    q = json.load(open(sys.argv[1], encoding="utf-8"))
    f = make_f(q["rule"], q["params"])
    form, a = q["form"], q["q"]
    lo, hi = (10 ** (abs(q["params"]["d"]) - 1), 10 ** abs(q["params"]["d"]) - 1) if q["rule"] == 'F' else (1, 200000)
    if form == 'min_gt':
        print(next(n for n in range(lo, hi + 1) if f(n) > a['X']))
    elif form == 'min_ge':
        print(next(n for n in range(lo, hi + 1) if f(n) >= a['X']))
    elif form == 'max_le':
        print(max(f(n) for n in range(1, a['M'] + 1)))
    elif form == 'min_eq':
        print(next(n for n in range(lo, hi + 1) if f(n) == a['X']))
    elif form == 'max_eq':
        print(max(n for n in range(lo, hi + 1) if f(n) == a['X']))
    elif form == 'count':
        print(len(set(f(n) for n in range(a['a'], a['b'] + 1))))
    elif form == 'count_n':
        print(sum(1 for n in range(lo, hi + 1) if f(n) == a['X']))


main()

